"import fs from 'fs';

const glbPath = "C:/Users/Shadow/.gemini/antigravity/scratch/fantastic-octo-giggle/public/models/Bottom_hinge_right.glb";

try {
  const buffer = fs.readFileSync(glbPath);

  // Read GLB header
  const magic = buffer.toString('utf8', 0, 4);
  const version = buffer.readUInt32LE(4);
  const length = buffer.readUInt32LE(8);

  console.log(`GLB Magic: ${magic}, Version: ${version}, Total Length: ${length}`);

  if (magic !== 'glTF') {
    throw new Error('Not a valid glTF/GLB file');
  }

  // Read Chunk 0 (JSON) header
  const chunkLength = buffer.readUInt32LE(12);
  const chunkType = buffer.toString('utf8', 16, 20);

  console.log(`Chunk 0 Length: ${chunkLength}, Type: ${chunkType}`);

  if (chunkType !== 'JSON') {
    throw new Error('First chunk must be JSON');
  }

  const jsonStr = buffer.toString('utf8', 20, 20 + chunkLength);
  const gltf = JSON.parse(jsonStr);

  console.log("\nNodes in GLB:");
  gltf.nodes.forEach((node, idx) => {
    console.log(`Node [${idx}]: Name="${node.name || 'unnamed'}", Mesh=${node.mesh !== undefined ? node.mesh : 'none'}, Children=${JSON.stringify(node.children || [])}`);
  });

  if (gltf.meshes) {
    console.log("\nMeshes in GLB:");
    gltf.meshes.forEach((mesh, idx) => {
      console.log(`Mesh [${idx}]: Name="${mesh.name || 'unnamed'}", Primitives=${mesh.primitives.length}`);
    });
  }

} catch (err) {
  console.error("Error reading GLB file:", err);
}
