"import fs from 'fs';

const glbPath = "C:/Users/Shadow/.gemini/antigravity/scratch/fantastic-octo-giggle/public/models/Bottom_hinge_right.glb";

try {
  const buffer = fs.readFileSync(glbPath);
  const chunkLength = buffer.readUInt32LE(12);
  const jsonStr = buffer.toString('utf8', 20, 20 + chunkLength);
  const gltf = JSON.parse(jsonStr);

  console.log("Detailed Node Hierarchy:");
  gltf.nodes.forEach((node, idx) => {
    console.log(`\nNode [${idx}]: "${node.name || 'unnamed'}"`);
    console.log(`  Mesh Ref: ${node.mesh !== undefined ? node.mesh : 'none'}`);
    if (node.translation) console.log(`  Translation: [${node.translation.join(', ')}]`);
    if (node.rotation) console.log(`  Rotation (quaternion): [${node.rotation.join(', ')}]`);
    if (node.scale) console.log(`  Scale: [${node.scale.join(', ')}]`);
    if (node.matrix) console.log(`  Matrix: [${node.matrix.join(', ')}]`);
    if (node.children) console.log(`  Children: ${JSON.stringify(node.children)}`);
  });

